<a class="back" href="/dashboard">← Dashboard</a><div class="actions" style="justify-content:space-between"><h1>Products</h1><a class="btn" href="/products/new">Add product</a></div><table><tr><th>Name</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($products as $p): ?><tr><td><?= esc($p['name']) ?></td><td>$<?= number_format($p['price'],2) ?></td><td><?= esc($p['stock_quantity']) ?></td><td class="actions"><a class="btn secondary" href="/products/<?= $p['id'] ?>/edit">Edit</a><form method="post" action="/products/<?= $p['id'] ?>" onsubmit="return confirm('Delete this product?')" style="padding:0;border:0;box-shadow:none"><?= csrf_field() ?><input type="hidden" name="_method" value="DELETE"><button class="btn danger">Delete</button></form></td></tr><?php endforeach ?></table>
